//! Explicit Nominatim-jsonv2 search and OSRM-GeoJSON route adapters.
//! No automatic provider, GPS, autocomplete, provider switching or turn-by-turn guidance.
use crate::*;
#[derive(Clone)]pub struct Provider{pub endpoint:String,pub attribution:String}
impl Provider{
 pub fn new(endpoint:&str,attribution:&str)->Result<Self,String>{
  let rest=endpoint.strip_prefix("https://").ok_or("Configure an HTTPS provider")?;let host=rest.split('/').next().unwrap_or("");
  if endpoint.len()>256||endpoint.chars().any(|c|c.is_control()||c.is_whitespace()||"?#@\\{}".contains(c))||host.len()>253||host.split('.').count()<2||host.split('.').any(|p|p.is_empty()||!p.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-')||p.starts_with('-')||p.ends_with('-'))||attribution.trim().is_empty()||attribution.len()>300||attribution.chars().any(char::is_control){return Err("Configure a keyless HTTPS endpoint and visible provider credits".into())}
  // Public shared services need host-wide policy/contact qualification; no unsafe public default.
  if ["nominatim.openstreetmap.org","router.project-osrm.org"].contains(&host.to_ascii_lowercase().as_str()){return Err("Configure your chosen provider; public shared demo endpoints are not enabled".into())}
  Ok(Self{endpoint:endpoint.trim_end_matches('/').into(),attribution:attribution.into()})
 }
}
fn encode(s:&str)->String{let mut out=String::new();for b in s.bytes(){if b.is_ascii_alphanumeric()||b"-._~".contains(&b){out.push(b as char)}else{out.push_str(&format!("%{b:02X}"))}}out}
fn coord(lat:f64,lon:f64)->Result<(),String>{if !lat.is_finite()||!lon.is_finite()||lat.abs()>85.05112878||lon.abs()>180.{Err("Coordinates exceed the supported Mercator map area".into())}else{Ok(())}}
fn text(v:&Value,max:usize)->Result<&str,String>{v.as_str().filter(|s|!s.trim().is_empty()&&s.chars().count()<=max&&!s.chars().any(char::is_control)).ok_or("Provider returned invalid display text".into())}
fn response(r:&Value)->Result<Value,String>{if r["status"]!=200{return Err("Map provider request failed; retry explicitly or use saved data".into())}http::parse_json(r)}
/// Endpoint is a full Nominatim-compatible search path. Call on explicit Search, never per keystroke.
pub fn search(p:&Provider,query:&str,then:&str)->Result<Value,String>{Provider::new(&p.endpoint,&p.attribution)?;let q=query.trim();if q.is_empty()||q.chars().count()>160||q.chars().any(char::is_control){return Err("Enter a place name up to160 characters".into())}Ok(http::get(&format!("{}?format=jsonv2&limit=5&addressdetails=0&q={}",p.endpoint,encode(q)),then))}
pub fn places(p:&Provider,r:&Value)->Result<Value,String>{Provider::new(&p.endpoint,&p.attribution)?;let raw=response(r)?;let rows=raw.as_array().filter(|v|v.len()<=5).ok_or("Geocoder returned too many or invalid places")?;let mut items=Vec::new();for row in rows{let lat=row["lat"].as_str().and_then(|s|s.parse::<f64>().ok()).ok_or("Invalid geocoder latitude")?;let lon=row["lon"].as_str().and_then(|s|s.parse::<f64>().ok()).ok_or("Invalid geocoder longitude")?;coord(lat,lon)?;items.push(json!({"label":text(&row["display_name"],240)?,"latitude":lat,"longitude":lon}));}Ok(json!({"items":items,"attribution":p.attribution,"empty":items.is_empty()}))}
/// Configure the OSRM route-v1 prefix; profile support depends on the selected provider.
pub fn route(p:&Provider,profile:&str,points:&[(f64,f64)],then:&str)->Result<Value,String>{Provider::new(&p.endpoint,&p.attribution)?;if !["driving","walking","cycling"].contains(&profile)||!(2..=8).contains(&points.len()){return Err("Choose a configured route profile and2–8 points".into())}let mut coords=Vec::new();for &(lat,lon)in points{coord(lat,lon)?;coords.push(format!("{lon:.7},{lat:.7}"));}Ok(http::get(&format!("{}/{}/{}?alternatives=false&steps=false&geometries=geojson&overview=simplified",p.endpoint,profile,coords.join(";")),then))}
pub fn route_result(p:&Provider,r:&Value)->Result<Value,String>{Provider::new(&p.endpoint,&p.attribution)?;let raw=response(r)?;if raw["code"]=="NoRoute"{return Err("No route was found between these points".into())}if raw["code"]!="Ok"{return Err("Route provider could not process these points".into())}let routes=raw["routes"].as_array().filter(|v|v.len()==1).ok_or("Expected one bounded route")?;let row=&routes[0];let distance=row["distance"].as_f64().filter(|v|v.is_finite()&&*v>=0.&&*v<=100_000_000.).ok_or("Invalid route distance")?;let duration=row["duration"].as_f64().filter(|v|v.is_finite()&&*v>=0.&&*v<=10_000_000.).ok_or("Invalid route duration")?;
 if row["geometry"]["type"]!="LineString"{return Err("Expected GeoJSON route geometry".into())}let coordinates=row["geometry"]["coordinates"].as_array().filter(|v|(2..=2048).contains(&v.len())).ok_or("Route geometry exceeds2048 points")?;let mut points=Vec::new();for pair in coordinates{let a=pair.as_array().filter(|a|a.len()==2).ok_or("Invalid route coordinate")?;let lon=a[0].as_f64().ok_or("Invalid route longitude")?;let lat=a[1].as_f64().ok_or("Invalid route latitude")?;coord(lat,lon)?;points.push(json!({"latitude":lat,"longitude":lon}));}Ok(json!({"distance_m":distance,"duration_s":duration,"points":points,"attribution":p.attribution,"guidance":false}))
}
/// Accessible native result rows; action suffix is the stable zero-based item index.
pub fn place_rows(result:&Value,prefix:&str)->Vec<Node>{let mut rows=vec![label("maps.geo.credits",result["attribution"].as_str().unwrap_or(""))];for(i,row)in result["items"].as_array().into_iter().flatten().take(5).enumerate(){rows.push(record(&format!("{prefix}.{i}"),row["label"].as_str().unwrap_or("Place"),&format!("{}, {}",row["latitude"],row["longitude"])))}if result["empty"]==true{rows.push(label("maps.geo.empty","No places found. Try a different name."));}rows}
/// Add bounded route geometry to an existing private raster map; native host validates again.
pub fn with_route(mut viewer:Node,result:&Value)->Result<Node,String>{let points=result["points"].as_array().filter(|p|(2..=2048).contains(&p.len())).ok_or("Choose a bounded route")?;for p in points{coord(p["latitude"].as_f64().ok_or("Missing latitude")?,p["longitude"].as_f64().ok_or("Missing longitude")?)?;}viewer["route"]=json!({"points":points,"attribution":text(&result["attribution"],300)?});Ok(viewer)}
#[cfg(test)]mod tests{
 use super::*;fn p()->Provider{Provider::new("https://geo.example.org/search","Demo provider · © OpenStreetMap contributors").unwrap()}fn r(v:Value)->Value{json!({"status":200,"text":v.to_string(),"headers":{}})}
 #[test]fn geo_search_encodes_unicode_and_does_not_enable_public_autocomplete(){let e=search(&p(),"café & lake","done").unwrap();assert!(e["args"]["url"].as_str().unwrap().ends_with("q=caf%C3%A9%20%26%20lake"));assert!(search(&p()," ","done").is_err());assert!(Provider::new("https://nominatim.openstreetmap.org/search","OSM").is_err());assert!(Provider::new("https://user@example.org/search","OSM").is_err());}
 #[test]fn geo_places_normalize_coordinates_and_fail_on_bad_or_oversized_results(){let v=places(&p(),&r(json!([{"lat":"40.1","lon":"-80.2","display_name":"Town"}]))).unwrap();assert_eq!(v["items"][0]["longitude"],-80.2);assert_eq!(place_rows(&v,"pick")[1]["id"],"pick.0");assert_eq!(places(&p(),&r(json!([]))).unwrap()["empty"],true);for v in [json!([{"lat":"NaN","lon":"1","display_name":"Bad"}]),json!([{"lat":"90","lon":"1","display_name":"Polar"}]),json!([{"lat":"1","lon":"1","display_name":"x".repeat(241)}])]{assert!(places(&p(),&r(v)).is_err());}}
 #[test]fn geo_routing_orders_lon_lat_and_rejects_unsafe_profiles_and_coordinates(){let e=route(&p(),"driving",&[(40.,-80.),(41.,-81.)],"done").unwrap();assert!(e["args"]["url"].as_str().unwrap().contains("-80.0000000,40.0000000;-81.0000000,41.0000000"));assert!(route(&p(),"../evil",&[(0.,0.),(1.,1.)],"done").is_err());assert!(route(&p(),"driving",&[(0.,0.)],"done").is_err());}
 #[test]fn geo_route_normalizes_summary_and_geometry_without_turn_by_turn_claims(){let raw=json!({"code":"Ok","routes":[{"distance":1200.,"duration":180.,"geometry":{"type":"LineString","coordinates":[[-80.,40.],[-81.,41.]]}}]});let route=route_result(&p(),&r(raw.clone())).unwrap();assert_eq!(route["points"][0]["latitude"],40.);assert_eq!(route["guidance"],false);assert!(with_route(json!({"kind":"map_viewer"}),&route).unwrap()["route"]["points"].is_array());let mut bad=raw;bad["routes"][0]["distance"]=json!(-1);assert!(route_result(&p(),&r(bad)).is_err());assert!(route_result(&p(),&r(json!({"code":"NoRoute"}))).is_err());assert!(places(&p(),&json!({"status":429,"text":"private provider response"})).is_err());}
}
